<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';import {workTypes,importanceLabels,assignmentLabels,currentAssignments} from '../department-work';import PersonDrawer from '../components/PersonDrawer.vue';import {countPersonAssignments} from '../../../lib/workspace/organization-rules';import {managerRoles} from '../organization';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const data=ref<any>(null),loading=ref(false),error=ref(''),section=ref('overview'),view=ref('work'),search=ref(''),category=ref(''),inactive=ref(false);
async function load(){loading.value=true;error.value='';try{data.value=await api('department-work?department='+props.tab.recordId);}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
const items=computed(()=>(data.value?.items||[]).filter((i:any)=>(inactive.value||i.status==='active')&&(!category.value||i.category_id===category.value)&&[i.title,i.purpose,...currentAssignments(i).map((a:any)=>a.user?.full_name)].some(v=>String(v||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
const activeItems=computed(()=>(data.value?.items||[]).filter((i:any)=>i.status==='active'));
const missingPrimary=computed(()=>activeItems.value.filter((i:any)=>!currentAssignments(i).some((a:any)=>a.assignment_type==='PRIMARY')).length);
const missingBackup=computed(()=>activeItems.value.filter((i:any)=>!currentAssignments(i).some((a:any)=>a.assignment_type==='BACKUP')).length);
const people=computed(()=>{const map=new Map<string,any>();for(const item of items.value){for(const a of currentAssignments(item)){if(!map.has(a.user_id))map.set(a.user_id,{id:a.user_id,user:a.user,items:[]});map.get(a.user_id).items.push({item,role:a.assignment_type});}}return [...map.values()];});
function open(item?:any){const tab=work.open('department-work-editor','',item?.id);tab.payload={departmentId:props.tab.recordId};tab.title=item?'職掌 · '+item.title:'新增職掌 · '+data.value.department.name;}
function editOrganization(mode='basic'){const tab=work.open('organization-editor','',props.tab.recordId);tab.payload={mode};tab.title=(mode==='members'?'成員':mode==='managers'?'主管':'部門')+' · '+data.value.department.name;}
const drawerUser=ref<any>(null);const managerOf=(userId:string)=>data.value?.managers.find((m:any)=>m.user_id===userId);
const names=(i:any,role:string)=>currentAssignments(i).filter((a:any)=>a.assignment_type===role).map((a:any)=>a.user?.full_name||a.user?.email).join('、')||'未指派';
watch([()=>work.departmentRevision,()=>work.organizationRevision],()=>{if(!loading.value)void load();});onMounted(load);
</script><template><header class="page-heading"><div><p class="eyebrow">部門管理 / {{data?.department.code}}</p><h1>{{data?.department.name||'部門工作頁'}}</h1></div><div class="actions"><button :disabled="loading" @click="load">重新載入</button><button v-if="data?.canManage" class="primary" @click="open()">新增工作職掌</button></div></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="loading" role="status">載入部門資料…</p><template v-if="data"><p v-if="data.department.status==='inactive'" class="notice">此部門已停用，工作職掌目前為唯讀。</p><nav class="sections" aria-label="部門內容"><button v-for="(label,key) in {overview:'概況',members:'成員',responsibilities:'工作職掌'}" :aria-pressed="section===key" :class="{primary:section===key}" @click="section=key">{{label}}</button></nav>
<section v-if="section==='overview'"><h2>部門概況</h2><div class="actions"><button v-if="data.organizationCapabilities.edit" @click="editOrganization()">編輯部門</button><button v-if="data.organizationCapabilities.managers" @click="editOrganization('managers')">設定主管</button></div><p class="description">{{data.department.description||'尚未填寫部門說明'}}</p><dl><dt>啟用中的職掌</dt><dd>{{activeItems.length}} 項</dd><dt>尚無主責</dt><dd>{{missingPrimary}} 項</dd><dt>尚無代理</dt><dd>{{missingBackup}} 項</dd><dt>直接成員</dt><dd>{{data.members.length}} 位</dd></dl><h2>部門主管</h2><p v-if="!data.managers.length">尚未設定主管</p><p v-for="m in data.managers" :key="m.id">{{m.user?.full_name||m.user?.email}}{{m.is_primary?'（主要主管）':''}}</p></section>
<section v-else-if="section==='members'"><h2>部門成員</h2><button v-if="data.organizationCapabilities.members" @click="editOrganization('members')">設定成員</button><p v-if="!data.members.length">尚未設定成員</p><div class="table-wrap"><table><thead><tr><th>人員</th><th>職稱</th><th>組織角色</th><th>主責</th><th>協作</th><th>代理</th><th>成員類型</th></tr></thead><tbody><tr v-for="m in data.members" :key="m.id" data-testid="member-row"><td><button class="link" type="button" :disabled="!m.user" @click="drawerUser=m.user">{{m.user?.employee_code}} {{m.user?.full_name||m.user?.email}}</button></td><td>{{m.user?.job_title||'—'}}</td><td>{{managerOf(m.user_id)?managerRoles[managerOf(m.user_id).manager_role]:'部門成員'}}</td><td data-testid="count-PRIMARY">{{countPersonAssignments(data.items,m.user_id,'PRIMARY')}}</td><td data-testid="count-COLLABORATOR">{{countPersonAssignments(data.items,m.user_id,'COLLABORATOR')}}</td><td data-testid="count-BACKUP">{{countPersonAssignments(data.items,m.user_id,'BACKUP')}}</td><td>{{m.is_primary?'主要組織成員':'其他成員'}}</td></tr></tbody></table></div></section>
<section v-else><div class="filters"><label>搜尋職掌或人員<input v-model="search" placeholder="名稱、目的或指派人員"></label><label>分類<select aria-label="職掌分類篩選" v-model="category"><option value="">全部分類</option><option v-for="c in data.categories" :value="c.id">{{c.name}}</option></select></label><label class="check"><input type="checkbox" v-model="inactive">包含停用職掌</label></div><div class="actions"><button :aria-pressed="view==='work'" @click="view='work'">按工作查看</button><button :aria-pressed="view==='person'" @click="view='person'">按人員查看</button><span>{{items.length}} 項職掌</span></div><div v-if="view==='work'" class="table-wrap"><table><thead><tr><th>工作職掌</th><th>分類／性質</th><th>主責</th><th>協作</th><th>代理</th><th>狀態</th><th>操作</th></tr></thead><tbody><tr v-for="i in items" :key="i.id"><td><strong>{{i.title}}</strong><small>{{importanceLabels[i.importance]}}</small></td><td>{{data.categories.find((c:any)=>c.id===i.category_id)?.name||'未分類'}}<small>{{workTypes[i.work_type]}}</small></td><td>{{names(i,'PRIMARY')}}</td><td>{{names(i,'COLLABORATOR')}}</td><td>{{names(i,'BACKUP')}}</td><td>{{i.status==='active'?'啟用':'停用'}}</td><td><button @click="open(i)">{{data.canManage?'查看／編輯':'查看內容'}}</button></td></tr></tbody></table></div><div v-else><section v-for="p in people" :key="p.id" class="person-work"><h2>{{p.user?.employee_code}} {{p.user?.full_name||p.user?.email}}</h2><div v-for="assignment in p.items" :key="assignment.item.id+assignment.role" class="person-work-row"><span>{{assignmentLabels[assignment.role]}} · {{assignment.item.title}}</span><button @click="open(assignment.item)">查看職掌</button></div></section><p v-if="!people.length">篩選結果中尚無人員指派</p><p v-if="items.some((i:any)=>!currentAssignments(i).length)">部分職掌尚未指派人員，可切回按工作查看核對。</p></div><p v-if="!items.length">{{data.items.length?'沒有符合條件的職掌':'尚無工作職掌。'}}</p></section><PersonDrawer v-if="drawerUser" :user="drawerUser" :department-id="data.department.id" :department-name="data.department.name" :items="data.items" :categories="data.categories" @close="drawerUser=null"/></template></template>
<style scoped>.actions,.sections,.filters{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.sections{border-bottom:1px solid var(--line);padding-bottom:16px;margin:20px 0}.filters{margin:24px 0;align-items:end}.filters>label{display:grid;gap:8px}.filters>label:first-child{min-width:220px;flex:1}.filters .check{display:flex;align-items:center;padding:10px}.check input{width:18px;height:18px;min-width:18px;min-height:18px}.table-wrap{overflow:auto;margin-top:16px}table{min-width:700px}small{display:block;color:var(--muted);margin-top:6px}h2{font-size:18px}.description{white-space:pre-wrap}dl{display:grid;grid-template-columns:180px 1fr;gap:12px;max-width:600px}dd{margin:0}.person-work{padding:20px 0;border-bottom:1px solid var(--line)}button.link{border:0;background:none;color:var(--primary);text-decoration:underline;padding:0;min-height:0;text-align:left}.person-work-row{display:flex;gap:16px;justify-content:space-between;padding:8px 0}</style>
